export function sym(name, x, y, s, c = '#1f2937', a = '#c8102e') {
  const fn = SYM[name];
  if (!fn) throw new Error(`no symbol "${name}"`);
  return fn(x, y, s, c, a);
}
export const hasSym = (name) => name in SYM;

// ---------- banners ----------
// A card banner: sky/backdrop, up to 3 flags on the left, up to 3 symbols, a dark caption bar at the bottom.
export function banner(x, y, w, h, spec) {
  const bg = spec.bg ?? ['#dbe7f3', '#f6f1e6'];
  const id = `bb${++clipSeq}`;
  let s = `<defs><linearGradient id="${id}g" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="${bg[0]}"/><stop offset="1" stop-color="${bg[1]}"/></linearGradient><clipPath id="${id}"><rect x="${x}" y="${y}" width="${w}" height="${h}"/></clipPath></defs>`;
  s += `<g clip-path="url(#${id})"><rect x="${x}" y="${y}" width="${w}" height="${h}" fill="url(#${id}g)"/>`;
  if (spec.ground) s += `<rect x="${x}" y="${y + h * 0.72}" width="${w}" height="${h * 0.28}" fill="${spec.ground}"/>`;
  const capH = spec.caption ? Math.round(h * 0.26) : 0;
  const ih = h - capH;
  const flags = spec.flags ?? [];
  const fh = Math.min(ih * 0.42, 24), fw = fh * 1.5;
  flags.forEach((f, i) => { s += flag(f, x + 7 + i * (fw + 4), y + 7, fw, fh); });
  const syms = spec.syms ?? [];
  const ss = Math.min(ih * 0.86, w / (syms.length + 1.2));
  const startX = x + w - 6 - syms.length * (ss + 2);
  syms.forEach((nm, i) => {
    const [name, c, a] = Array.isArray(nm) ? nm : [nm];
    s += sym(name, startX + i * (ss + 2), y + (ih - ss) / 2 + 1, ss, c ?? spec.ink ?? '#1f2937', a ?? spec.accent ?? '#c8102e');
  });
  if (spec.big) s += `<text x="${x + 8}" y="${y + ih - 8}" font-family="Georgia, serif" font-weight="bold" font-size="${Math.round(ih * 0.4)}" fill="${spec.bigColor ?? '#0f1d3a'}">${esc(spec.big)}</text>`;
  if (capH) s += `<rect x="${x}" y="${y + h - capH}" width="${w}" height="${capH}" fill="rgba(15,23,42,.88)"/><text x="${x + 6}" y="${y + h - capH / 2 + 3.6}" font-family="Arial, Helvetica, sans-serif" font-weight="bold" font-size="${Math.min(10, capH * 0.62)}" letter-spacing=".3" fill="#fff">${esc(spec.caption)}</text>`;
  s += `</g>`;
  return s;
}

export { esc };
